import sys

if sys.version_info < (3, 11):
    import typing

    class _SelfType:
        def __getitem__(self, item):
            return item

        def __or__(self, other):
            return object

        def __ror__(self, other):
            return object

        def __repr__(self):
            return "typing.Self"

    typing.Self = _SelfType()
